BEGIN;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE atlas_item_type AS ENUM ('place','project','event','publication','actor','concept');
CREATE TYPE publication_status AS ENUM ('draft','review','published','archived');
CREATE TABLE atlas_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slug TEXT NOT NULL UNIQUE,item_type atlas_item_type NOT NULL,title TEXT NOT NULL,summary TEXT,body JSONB NOT NULL DEFAULT '{}'::jsonb,status publication_status NOT NULL DEFAULT 'draft',published_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),created_by UUID,updated_by UUID,CHECK(status<>'published' OR published_at IS NOT NULL));
CREATE INDEX atlas_items_status_type_idx ON atlas_items(status,item_type);
CREATE INDEX atlas_items_search_idx ON atlas_items USING GIN(to_tsvector('german',coalesce(title,'')||' '||coalesce(summary,'')));
CREATE TABLE topics(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slug TEXT NOT NULL UNIQUE,label TEXT NOT NULL,description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE item_topics(item_id UUID NOT NULL REFERENCES atlas_items(id) ON DELETE CASCADE,topic_id UUID NOT NULL REFERENCES topics(id) ON DELETE CASCADE,PRIMARY KEY(item_id,topic_id));
CREATE TABLE spatial_features(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),item_id UUID NOT NULL REFERENCES atlas_items(id) ON DELETE CASCADE,role TEXT NOT NULL DEFAULT 'primary',geom geometry(Geometry,4326) NOT NULL,precision TEXT NOT NULL DEFAULT 'approximate',provenance TEXT,valid_from DATE,valid_to DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(valid_to IS NULL OR valid_from IS NULL OR valid_to>=valid_from));
CREATE INDEX spatial_features_geom_gix ON spatial_features USING GIST(geom);
CREATE INDEX spatial_features_item_idx ON spatial_features(item_id);
CREATE TABLE relations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),source_item_id UUID NOT NULL REFERENCES atlas_items(id) ON DELETE CASCADE,target_item_id UUID NOT NULL REFERENCES atlas_items(id) ON DELETE CASCADE,relation_type TEXT NOT NULL,description TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(source_item_id<>target_item_id),UNIQUE(source_item_id,target_item_id,relation_type));
CREATE INDEX relations_source_idx ON relations(source_item_id);
CREATE INDEX relations_target_idx ON relations(target_item_id);
CREATE TABLE sources(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),title TEXT NOT NULL,citation TEXT,url TEXT,source_type TEXT,license TEXT,accessed_at DATE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE item_sources(item_id UUID NOT NULL REFERENCES atlas_items(id) ON DELETE CASCADE,source_id UUID NOT NULL REFERENCES sources(id) ON DELETE CASCADE,note TEXT,PRIMARY KEY(item_id,source_id));
CREATE TABLE map_layers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT,config JSONB NOT NULL DEFAULT '{}'::jsonb,is_public BOOLEAN NOT NULL DEFAULT false,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE map_views(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT,center geometry(Point,4326),zoom NUMERIC(5,2),filters JSONB NOT NULL DEFAULT '{}'::jsonb,is_public BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE contributions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),item_id UUID REFERENCES atlas_items(id) ON DELETE SET NULL,submitter_name TEXT,submitter_contact TEXT,payload JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'submitted',moderation_note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_at TIMESTAMPTZ);
CREATE TABLE datasets(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT,license TEXT,source_url TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,imported_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE FUNCTION set_updated_at() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER atlas_items_updated_at BEFORE UPDATE ON atlas_items FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER spatial_features_updated_at BEFORE UPDATE ON spatial_features FOR EACH ROW EXECUTE FUNCTION set_updated_at();
COMMIT;
